export const mathLevels=[{id:0,label:'Start with counting',description:'Flowers and birds · one, two, three.'},{id:1,label:'Count, join and share',description:'The first five little lessons.'},{id:2,label:'More little adventures',description:'All twelve lessons · use adult help for new language.'}];
export const mathSteps=(l,extra=false)=>{const source=extra?l.extra:l;return source?[...source.words.map(word=>({type:'word',word,...mathWords[word],...(word==='each'&&l.id==='math-baskets'?{meaning:'প্রতিটি',text:'Two apples in each basket.',scene:'baskets'}:{})})),...source.sentences,...source.questions,{type:'finish'}]:[];};
export const mathQuestionId=(l,q)=>'math:'+l.id+':'+q.id;
export const mathDemonstration=q=>'Let’s look together. The answer is '+q.choices.find(c=>c.id===q.answer).label+'. '+q.feedback.replace(/^Yes!\s*/, '')+' Try again.';
export const mathReviewItems=mathLessons.flatMap(l=>[...l.questions,...(l.extra?.questions||[])].map(q=>({...q,id:mathQuestionId(l,q),questionId:q.id,kind:'math',label:l.title+' · '+l.skill,lessonId:l.id,skill:l.skill})));
const normalizeAttempt=r=>({tries:Number.isInteger(r?.tries)?Math.max(0,Math.min(10000,r.tries)):0,misses:Number.isInteger(r?.misses)?Math.max(0,Math.min(10000,r.misses)):0,assisted:r?.assisted===true,firstCorrect:typeof r?.firstCorrect==='boolean'?r.firstCorrect:null});
export function normalizeMath(raw){
 const out={level:[0,1,2].includes(raw?.level)?raw.level:0,current:mathLessons.some(l=>l.id===raw?.current)?raw.current:null,wordsMet:[...new Set((Array.isArray(raw?.wordsMet)?raw.wordsMet:[]).filter(w=>mathWords[w]))],lessons:{}};
 for(const l of mathLessons){const p=raw?.lessons?.[l.id];if(!p)continue;const questions=[...l.questions,...(l.extra?.questions||[])],answers={},attempts={};for(const q of questions){if(q.choices.some(c=>c.id===p.answers?.[q.id]))answers[q.id]=p.answers[q.id];if(p.attempts?.[q.id])attempts[q.id]=normalizeAttempt(p.attempts[q.id]);}const valid=(n,max)=>Number.isInteger(n)&&n>=0&&n<max,core=mathSteps(l).length,extra=mathSteps(l,true).length;
  out.lessons[l.id]={step:valid(p.step,core)?p.step:0,extra:!!l.extra&&p.extra===true,extraStep:valid(p.extraStep,extra)?p.extraStep:0,done:p.done===true,extraDone:!!l.extra&&p.extraDone===true,answers,attempts,completed:[...new Set((Array.isArray(p.completed)?p.completed:[]).filter(n=>valid(n,core)))],extraCompleted:[...new Set((Array.isArray(p.extraCompleted)?p.extraCompleted:[]).filter(n=>valid(n,extra)))]};
 }return out;
}
